def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

    rates = {
        "inland": Decimal("4.20"),
        "coastal": Decimal("5.75"),
        "highland": Decimal("9.10"),
    }

    if zone not in rates:
        raise ValueError("invalid zone")

    try:
        weight = Decimal(str(weight_kg))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError("invalid weight")

    if not weight.is_finite() or weight <= 0:
        raise ValueError("weight must be greater than zero")

    base = rates[zone]
    first_tier = min(weight, Decimal("10")) * base
    second_tier = min(max(weight - Decimal("10"), Decimal("0")), Decimal("40")) * Decimal("0.60") * base
    third_tier = max(weight - Decimal("50"), Decimal("0")) * Decimal("0.35") * base

    subtotal = (first_tier + second_tier + third_tier).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )

    if subtotal % Decimal("1") == 0:
        subtotal -= Decimal("2.00")

    if is_perishable and zone != "highland":
        subtotal += Decimal("18.50")

    return float(subtotal.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

